<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>All orders</h1><p>Review system-wide order status and cash payment records.</p></div></div>
<form class="toolbar" method="get" action="<?= h(app_url('admin.orders')) ?>"><input type="hidden" name="r" value="admin.orders"><div class="form-field"><label for="status">Status</label><select id="status" name="status"><option value="">All statuses</option><?php foreach (ORDER_STATUSES as $candidate): ?><option value="<?= h($candidate) ?>"<?= $status===$candidate?' selected':'' ?>><?= h(status_label($candidate)) ?></option><?php endforeach; ?></select></div><button class="button button-secondary" type="submit">Filter</button></form>
<?php if ($orders): ?><div class="stack"><?php foreach ($orders as $order): $next=Order::allowedNext($order['status']); if ($order['status']==='READY' && !(int)($order['no_show_allowed']??0)) $next=array_values(array_diff($next,['NO_SHOW'])); ?><article class="panel"><div class="spread"><div><h2 class="panel-title" style="margin:0"><?= h($order['order_number']) ?></h2><p class="muted small" style="margin:4px 0 0"><?= h($order['student_name'] ?: 'POS sale') ?> · <?= h($order['vendor_name']) ?> · <?= h(format_datetime($order['created_at'])) ?></p></div><div class="stack" style="justify-items:end;gap:5px"><?php $status=$order['status'];require APP_ROOT . '/views/components/status-badge.php'; ?><?php $status=$order['payment_status']??'UNPAID';require APP_ROOT . '/views/components/status-badge.php'; ?></div></div><div class="order-card-content"><div><strong><?= h(money($order['total'])) ?></strong><p class="muted small">Pickup: <?= h($order['pickup_location']) ?></p></div><?php if ($next): ?><form method="post" action="<?= h(app_url('admin.order.status')) ?>" class="order-action-form" data-submit-feedback><?= csrf_field() ?><input type="hidden" name="order_id" value="<?= (int)$order['id'] ?>"><div class="form-field"><label for="admin-status-<?= (int)$order['id'] ?>">Next status</label><select id="admin-status-<?= (int)$order['id'] ?>" name="status"><?php foreach ($next as $choice): ?><option value="<?= h($choice) ?>"><?= h(status_label($choice)) ?></option><?php endforeach; ?></select></div><?php if (in_array('COMPLETED', $next, true)): ?><div class="form-field"><label for="admin-cash-<?= (int)$order['id'] ?>">Cash received (₱) <span class="muted">(only to complete)</span></label><input id="admin-cash-<?= (int)$order['id'] ?>" name="cash_received" type="number" min="0" max="1000000" step="0.01" inputmode="decimal" placeholder="<?= h(number_format((float)$order['total'],2,'.','')) ?>"></div><?php endif; ?><button class="button button-secondary button-small" type="submit">Update</button></form><?php endif; ?></div><?php if ($order['source']==='STUDENT' && $order['status']==='READY'): ?><p class="cash-note">Student pickup: <?php if ((int)($order['no_show_allowed']??0)): ?>the <?= (int) PICKUP_GRACE_MINUTES ?>-minute window has elapsed. If uncollected, “Not picked up” leaves cash unpaid and does not return prepared food to stock.<?php else: ?>the “Not picked up” action becomes available after <?= (int) PICKUP_GRACE_MINUTES ?> minutes from Ready.<?php endif; ?></p><?php endif; ?></article><?php endforeach; ?></div><?php $routeName='admin.orders';$perPage=$limit;$queryParams=$status?['status'=>$status]:[];require APP_ROOT . '/views/components/pagination.php'; ?><?php else: ?><div class="empty-state"><h2>No orders found</h2><p>Try another status filter.</p></div><?php endif; ?>
